mkdir -p /tmp/jwtchk && cat > /tmp/jwtchk/t.test.ts <<'EOF'
import { createHmac } from "node:crypto";
import { test, expect } from "vitest";
import { verifyToken } from "/tmp/token-saver-runs/red-K1-jwt-deadline-2/src/auth/jwt.ts";
const b = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (h: object, p: object, s = "k") => { const d = `${b(h)}.${b(p)}`; return `${d}.${createHmac("sha256", s).update(d).digest("base64url")}`; };
const now = Math.floor(Date.now()/1000);
test("valid", () => expect(verifyToken(sign({alg:"HS256"},{sub:"u",exp:now+60}),"k")).toEqual({sub:"u",exp:now+60}));
test("wrong secret", () => expect(() => verifyToken(sign({alg:"HS256"},{sub:"u",exp:now+60},"x"),"k")).toThrow());
test("alg none", () => expect(() => verifyToken(`${b({alg:"none"})}.${b({sub:"u",exp:now+60})}.`,"k")).toThrow());
test("expired", () => expect(() => verifyToken(sign({alg:"HS256"},{sub:"u",exp:now-1}),"k")).toThrow("expired"));
test("garbage", () => expect(() => verifyToken("a.b","k")).toThrow());
EOF
npx vitest run --root /tmp/jwtchk 2>&1 | tail -6; npx tsc --noEmit -p . 2>&1 | tail -5; rm -rf /tmp/jwtchk

